<label>value <select name="action_value_mode"><option value="keep">keep stored value (not shown)</option><option value="replace">replace</option><option value="clear">clear to empty</option></select><input name="action_value" value="" autocomplete="off"></label>
{{if eq .kind "set_param"}}<label>where <select name="action_in"><option value="" {{if eq .in ""}}selected{{end}}>wherever it already is</option><option value="query" {{if eq .in "query"}}selected{{end}}>query string</option><option value="body" {{if eq .in "body"}}selected{{end}}>form body</option></select></label>{{end}}
{{end}}
