73	// ui2SessionRulesTools renders the tools axis as the review sheet must say it: an absent or
74	// empty selection is Burp's "every tool", never an empty restriction (the engine refuses an
75	// explicitly empty scope_tools list rather than silently widening it).
76	func ui2SessionRulesToolsNote(tools []string) string {
77		if len(tools) == 0 {
78			return "every tool"
79		}
80		return strings.Join(tools, ", ")
81	}
