83	// ui2SessionRuleDTO fetches one rule's dto map as GET /api/session/rules serves it, decoded with
84	// UseNumber so a merge re-marshal keeps number literals exact. False when the coordinator is not
85	// wired or the id is gone.
86	func (s *Server) ui2SessionRuleDTO(id int64) (map[string]any, bool) {
87		if s.sessionCoordinator == nil {
88			return nil, false
89		}
90		rec := newRecorder()
91		s.mux.ServeHTTP(rec, newReq(http.MethodGet, "/api/session/rules"))
92		var resp struct {
93			Rules []map[string]any `json:"rules"`
94		}
95		dec := json.NewDecoder(bytes.NewReader(rec.Body.Bytes()))
96		dec.UseNumber()
97		if err := dec.Decode(&resp); err != nil {
98			return nil, false
99		}
100		for _, rule := range resp.Rules {
101			if n, ok := rule["id"].(json.Number); ok {
102				if v, err := n.Int64(); err == nil && v == id {
103					return rule, true
104				}
105			}
106		}
107		return nil, false
108	}
