110	// ui2SessionRuleDigest is the compare-and-update precondition for a rule the coordinator holds.
111	func (s *Server) ui2SessionRuleDigest(id int64) (string, bool) {
112		if s.sessionCoordinator == nil {
113			return "", false
114		}
115		rule := s.sessionCoordinator.Rule(session.RuleID(id))
116		if rule == nil {
117			return "", false
118		}
119		return session.RuleDigest(rule), true
120	}
