122	// ui2SessionActionLabels reads the operator-facing action labels out of a served rule dto, for
123	// the toggle-on consequence line: "when on, this rule runs: <labels>". The API serves the labels
124	// (Burp's own words) so this page never keeps its own copy of the vocabulary.
125	func ui2SessionActionLabels(rule map[string]any) string {
126		actions, ok := rule["actions"].([]any)
127		if !ok || len(actions) == 0 {
128			return "the engine's default flow (check login validity, then run its macro)"
129		}
130		labels := make([]string, 0, len(actions))
131		for _, a := range actions {
132			if m, ok := a.(map[string]any); ok {
133				if l, ok := m["label"].(string); ok && l != "" {
134					labels = append(labels, l)
135					continue
136				}
137				if k, ok := m["kind"].(string); ok {
138					labels = append(labels, k)
139				}
140			}
141		}
142		return strings.Join(labels, "; ")
143	}
