157	// ui2SessionActionEffects describes what each served action DOES, for the toggle-on consequence:
158	// the operator enabling a rule is changing how matching requests get authenticated or rewritten,
159	// and the sheet must say that in words, not only name the kinds. Phrases come from the served
160	// kind and name fields; an unknown kind falls back to its served label rather than a guess.
161	func ui2SessionActionEffects(rule map[string]any) string {
162		actions, ok := rule["actions"].([]any)
163		if !ok || len(actions) == 0 {
164			return "the engine's default flow (check login validity, then replay its macro against the target)"
165		}
166		effects := make([]string, 0, len(actions))
167		for _, a := range actions {
168			m, ok := a.(map[string]any)
169			if !ok {
170				continue
171			}
172			kindName, _ := m["kind"].(string)
173			aname, _ := m["name"].(string)
174			label, _ := m["label"].(string)
175			kind, err := session.ParseActionKind(kindName)
176			if err != nil {
177				effects = append(effects, label)
178				continue
179			}
180			switch kind {
181			case session.ActionAddCookiesFromJar:
182				effects = append(effects, "attach the session cookie jar's cookies for the request's own host - if the jar holds none for that host, nothing is attached")
183			case session.ActionRunMacro, session.ActionRunPostRequestMacro:
184				effects = append(effects, "replay the rule's recorded macro against the target (its login requests run again)")
185			case session.ActionCheckValidity:
186				effects = append(effects, "check whether the current session is still valid and run its conditional sub-actions")
187			case session.ActionSetCookie:
188				effects = append(effects, fmt.Sprintf("set the %q cookie on matching requests", aname))
189			case session.ActionSetParam:
190				effects = append(effects, fmt.Sprintf("set the %q parameter on matching requests", aname))
191			case session.ActionSetHeader:
192				effects = append(effects, fmt.Sprintf("set the %q header on matching requests", aname))
193			default:
194				effects = append(effects, label)
195			}
196		}
197		return strings.Join(effects, "; ")
198	}
