200	// ui2SessionRuleProjection renders the review sheet's exact call from the FULL held body: the
201	// gate's own preview truncates (200 chars in the ui2 helper) and a label that says "exact" must
202	// not hide the expected_base precondition it asks the operator to approve. The rendering is the
203	// same CONTENT the token binds, re-encoded for display - the binding itself is computed from the
204	// minted bytes, which the run step dispatches verbatim.
205	//
206	// A full body is not a safe body to show: rules coming from the console can CARRY credentials -
207	// a set-cookie/set-header/set-param action's value, a macro step's login form body, an
208	// Authorization or Cookie header, an embedded script with a token inside. The projection
209	// withholds those values in the view (the token still binds them: the held bytes are
210	// dispatched untouched). Redaction here is domain-aware, not only the gate's key-name REDACTED:
211	// redactSecrets matches on member names, and a set-cookie action's secret sits in a generic
212	// "value" member whose sibling "name" is the cookie's name, not a secret-looking key.
213	func ui2SessionRuleProjection(method, url string, body []byte) string {
214		out := method + " " + url
215		if len(body) == 0 {
216			return out
217		}
218		var v any
219		dec := json.NewDecoder(bytes.NewReader(body))
220		dec.UseNumber()
221		if err := dec.Decode(&v); err != nil {
222			return out + "\n(unreadable body - " + strconv.Itoa(len(body)) + " bytes held)"
223		}
224		ui2SessionRuleRedact(v)
225		if pretty, err := json.MarshalIndent(v, "", "  "); err == nil {
226			return out + "\n" + string(pretty)
227		}
228		return out + "\n" + string(body)
229	}
