231	// ui2SessionRuleDomainProjection renders the review sheet's exact-change view for a
232	// coordinator-level install: the merged rule's domain marshal, redacted by the same walker the
233	// wire projection uses (its kind arms accept the domain's enum numbers), so what the sheet
234	// shows is field-for-field what the compare-and-update installs - minus the withheld values,
235	// which the token still binds. The op line names the operation rather than an HTTP call,
236	// because no request is dispatched on run.
237	func ui2SessionRuleDomainProjection(ruleID int64, expectedBase string, body []byte) string {
238		out := "Update stored rule " + strconv.FormatInt(ruleID, 10) + " in place (compare-and-update; installs only while the stored rule still digests to " + expectedBase + "; nothing is re-encoded through the session API)"
239		var v any
240		dec := json.NewDecoder(bytes.NewReader(body))
241		dec.UseNumber()
242		if err := dec.Decode(&v); err != nil {
243			return out + "\n(unreadable body - " + strconv.Itoa(len(body)) + " bytes held)"
244		}
245		ui2SessionRuleRedact(v)
246		if pretty, err := json.MarshalIndent(v, "", "  "); err == nil {
247			return out + "\n" + string(pretty)
248		}
249		return out + "\n" + string(body)
250	}
