252	// ui2SessionRuleRedact walks a decoded rule body withholding credential-carrying values in
253	// place. The generic key-name REDACTED runs first; the domain REDACTED then covers the shapes it
254	// cannot see: action values keyed by a generic "value", macro step bodies (the login form
255	// data), header PAIRS (two-element arrays, not the {name,value} maps redactSecrets knows),
256	// and embedded script source.
257	func ui2SessionRuleRedact(v any) {
258		redactSecrets(v, map[string]bool{})
259		ui2SessionRuleRedactDomain(v)
260	}
261	
262	func ui2SessionRuleRedactDomain(v any) {
263		switch t := v.(type) {
264		case map[string]any:
265			// kind arrives as the wire name on DTO-shaped bodies and as the enum number on a
266			// domain marshal (ActionKind has no custom JSON marshaler - verified by probe); both
267			// resolve to the same name before the per-kind arms decide what is withheld, or a
268			// domain projection would show a set_cookie's value in the clear.
269			kind, _ := t["kind"].(string)
270			if kind == "" {
271				if kn, ok := t["kind"].(json.Number); ok {
272					if ki, err := kn.Int64(); err == nil {
273						kind = session.ActionKindName(session.ActionKind(ki))
274					}
275				}
276			}
277			// extension_session is a free-form extension state blob (session.Action.ExtensionSession)
278			// that only a domain marshal carries - the wire DTO never serves it. secretMember does
279			// not match the name, so withhold it explicitly.
280			if v, ok := t["extension_session"].(string); ok && v != "" {
281				t["extension_session"] = redactedValue
282			}
283			if kind != "" {
284				switch kind {
285				case "set_cookie", "set_header", "set_param":
286					if val, ok := t["value"].(string); ok && val != "" {
287						t["value"] = redactedValue
288					}
289				case "replace":
290					// Replacement resolves macro-extracted placeholders (the engine's own
291					// actionPlaceholders classifies it with the set_* values), and a literal
292					// Match is very often the old token being rewritten - both are withheld.
293					for _, f := range []string{"replacement", "match"} {
294						if val, ok := t[f].(string); ok && val != "" {
295							t[f] = redactedValue
296						}
297					}
298				case "run_script":
299					if val, ok := t["script"].(string); ok && val != "" {
300						t["script"] = redactedValue
301					}
302				}
303			}
304			// A macro step is the map with method+url: its body is the login form data, its
305			// headers are [name, value] pairs, and its URL can itself carry a credential -
306			// userinfo (REDACTED or a token-style query value. The engine's
307			// placeholder classification does not decide that; the string does.
308			if _, hasMethod := t["method"].(string); hasMethod {
309				if stepURL, ok := t["url"].(string); ok {
310					if b, ok := t["body"].(string); ok && b != "" {
311						t["body"] = redactedValue
312					}
313					t["url"] = ui2SessionRuleSanitizeURL(stepURL)
314				}
315			}
316			for _, val := range t {
317				ui2SessionRuleRedactDomain(val)
318			}
319		case []any:
320			// A header pair: ["Authorization", "Bearer ..."] - withhold the value when the name is
321			// a credential carrier. Other pair arrays (none today) have no secret reading.
322			if len(t) == 2 {
323				if name, ok := t[0].(string); ok && secretMember.MatchString(name) {
324					if val, ok := t[1].(string); ok && val != "" {
325						t[1] = redactedValue
326						return
327					}
328				}
329			}
330			for _, item := range t {
331				ui2SessionRuleRedactDomain(item)
332			}
333		}
334	}
335	
336	// ui2SessionRuleSanitizeURL rewrites a macro step URL for display only, keeping the host and
337	// path visible for the operator's review while withholding the credential-carrying parts:
338	// userinfo (REDACTED is replaced with the redaction marker, and query values
339	// whose KEY names a credential (token, key, sig, REDACTEDword, ...) are withheld while innocuous
340	// parameters stay visible. Both rewrites are string surgery on the wire form, so the marker
341	// stays readable and no percent-decode shows a credential by accident. A URL that will not
342	// parse is withheld whole - fail closed, since an unparseable form may be hiding a credential
343	// in the part that could not be classified. The engine's placeholder classification does not
344	// decide whether a URL contains a secret; the string does.
345	func ui2SessionRuleSanitizeURL(raw string) string {
346		if _, err := url.Parse(raw); err != nil {
347			return redactedValue
348		}
349		work := raw
350		if i := strings.Index(work, "://"); i >= 0 {
351			rest := work[i+3:]
352			if at := strings.Index(rest, "@"); at >= 0 {
353				if end := strings.IndexAny(rest, "/?#"); end < 0 || at < end {
354					work = work[:i+3] + redactedValue + rest[at:]
355				}
356			}
357		}
358		mask := func(pairs string) string {
359			parts := strings.Split(pairs, "&")
360			for i, part := range parts {
361				eq := strings.IndexByte(part, '=')
362				if eq < 0 {
363					continue
364				}
365				if key, err := url.QueryUnescape(part[:eq]); err == nil && secretMember.MatchString(key) {
366					parts[i] = part[:eq+1] + redactedValue
367				}
368			}
369			return strings.Join(parts, "&")
370		}
371		if q := strings.IndexByte(work, '?'); q >= 0 {
372			tail := work[q+1:]
373			frag := ""
374			if h := strings.IndexByte(tail, '#'); h >= 0 {
375				frag = tail[h:]
376				tail = tail[:h]
377			}
378			work = work[:q+1] + mask(tail) + frag
379		}
380		// The fragment carries credentials in OAuth-style flows (#access_token=REDACTED mask
381		// secret-named pairs the same way. A fragment with no pairs and no path shape is a bare
382		// unclassifiable token - withhold it whole rather than guess.
383		if h := strings.IndexByte(work, '#'); h >= 0 {
384			frag := work[h+1:]
385			if frag != "" {
386				switch {
387				case strings.Contains(frag, "="):
388					work = work[:h+1] + mask(frag)
389				case strings.Contains(frag, "/"):
390					// a routed anchor (#/dashboard), no carrier shape
391				default:
392					work = work[:h+1] + redactedValue
393				}
394			}
395		}
396		return work
397	}
