399	// handleUI2SessionRules serves POST /ui2/session/rules/{action}: confirm mints and renders the
400	// review; run spends the held entry and dispatches the reviewed call.
401	func (s *Server) handleUI2SessionRules(w http.ResponseWriter, r *http.Request) {
402		switch r.PathValue("action") {
403		case "confirm":
404			s.ui2SessionRulesConfirm(w, r)
405		case "run":
406			s.ui2SessionRulesRun(w, r)
407		default:
408			http.Error(w, "unknown session rules action", http.StatusBadRequest)
409		}
410	}
