412	// ui2SessionRulePageKind reports whether the add form can create this action kind. Macros,
413	// validity checks and extension actions stay in the console: a fresh page rule has no macro
414	// steps to run, validity checks nest sub-actions, and an extension action names a registered
415	// extension, none of which a bounded form edits honestly. Multi-action rules and editing an
416	// existing rule's advanced fields stay there too.
417	func ui2SessionRulePageKind(k session.ActionKind) bool {
418		switch k {
419		case session.ActionAddCookiesFromJar, session.ActionSetCookie, session.ActionSetHeader,
420			session.ActionSetParam, session.ActionReplace, session.ActionRunScript,
421			session.ActionPromptForBrowserRecovery:
422			return true
423		}
424		return false
425	}
