427	// ui2SessionRuleActionFields lists every per-kind field the add form carries. The browser
428	// submits only the chosen kind's fields - the other kinds' controls stay disabled in the
429	// markup, and a disabled control is never successful - so one of these arriving for a kind
430	// that does not use it means a crafted or stale post, and the add is refused rather than the
431	// field ignored: the call the operator reviews must be the call they saw.
432	var ui2SessionRuleActionFields = []string{
433		"action_name", "action_value", "action_in",
434		"action_match", "action_replacement", "action_regex", "action_script",
435	}
436	
437	// ui2SessionRulePageAction builds the one action a page-created rule carries from exactly the
438	// fields its kind defines. Field values are taken verbatim - a cookie value's spaces and a
439	// match's leading whitespace are the operator's content, and the review sheet shows the bytes
440	// the token binds.
441	func ui2SessionRulePageAction(kind session.ActionKind, r *http.Request) (map[string]any, error) {
442		allowed := map[string]bool{}
443		action := map[string]any{"kind": session.ActionKindName(kind), "enabled": true}
444		switch kind {
445		case session.ActionAddCookiesFromJar, session.ActionPromptForBrowserRecovery:
446			// Fieldless kinds: any action_* field is foreign here.
447		case session.ActionSetCookie, session.ActionSetHeader:
448			allowed["action_name"], allowed["action_value"] = true, true
449			action["name"] = strings.TrimSpace(r.PostFormValue("action_name"))
450			action["value"] = r.PostFormValue("action_value")
451		case session.ActionSetParam:
452			allowed["action_name"], allowed["action_value"], allowed["action_in"] = true, true, true
453			action["name"] = strings.TrimSpace(r.PostFormValue("action_name"))
454			action["value"] = r.PostFormValue("action_value")
455			action["in"] = r.PostFormValue("action_in")
456		case session.ActionReplace:
457			allowed["action_match"], allowed["action_replacement"], allowed["action_regex"] = true, true, true
458			action["match"] = r.PostFormValue("action_match")
459			action["replacement"] = r.PostFormValue("action_replacement")
460			action["regex"] = r.PostFormValue("action_regex") != ""
461		case session.ActionRunScript:
462			allowed["action_script"] = true
463			action["script"] = r.PostFormValue("action_script")
464		}
465		for _, field := range ui2SessionRuleActionFields {
466			if allowed[field] {
467				continue
468			}
469			if _, sent := r.PostForm[field]; sent {
470				return nil, fmt.Errorf("the %s field does not belong to the %s action - the page you acted on was out of date", field, session.ActionKindLabel(kind))
471			}
472		}
473		return action, nil
474	}
