476	// ui2SessionRuleValidateAddBody validates the exact marshaled call the run step would dispatch:
477	// decoded by the API's own dtoToRule, then refused by the engine's validators - ValidateActions
478	// names the action's fault, and ValidateRule adds the rule-level placeholder check (a value
479	// naming a macro-extracted placeholder is refused: a page-created rule has no macro, so nothing
480	// extracts it). No page-side copy of the engine's checks exists to drift.
481	func ui2SessionRuleValidateAddBody(body []byte) error {
482		var dto sessionRuleDto
483		if err := json.Unmarshal(body, &dto); err != nil {
484			return err
485		}
486		rule, err := dtoToRule(dto)
487		if err != nil {
488			return err
489		}
490		if err := session.ValidateActions(rule.Actions); err != nil {
491			return err
492		}
493		return session.ValidateRule(rule)
494	}
