496	// ui2SessionRulePageActionSummary names the chosen action in the review's own words, without
497	// repeating its values - the sheet's projection is where content shows, withheld where it must be.
498	func ui2SessionRulePageActionSummary(kind session.ActionKind, action map[string]any) string {
499		switch kind {
500		case session.ActionAddCookiesFromJar:
501			return "add cookies from the session jar"
502		case session.ActionSetCookie:
503			return fmt.Sprintf("set the %q cookie", action["name"])
504		case session.ActionSetHeader:
505			return fmt.Sprintf("set the %q header", action["name"])
506		case session.ActionSetParam:
507			where := map[string]string{"": "wherever it already is", "query": "in the query string", "body": "in the form body"}[action["in"].(string)]
508			return fmt.Sprintf("set the %q parameter %s", action["name"], where)
509		case session.ActionReplace:
510			if action["regex"] == true {
511				return "replace what the regular expression matches"
512			}
513			return "replace the literal match"
514		case session.ActionRunScript:
515			return "run a pre-request script"
516		case session.ActionPromptForBrowserRecovery:
517			return "prompt for in-browser session recovery"
518		}
519		return session.ActionKindLabel(kind)
520	}
