782	// ui2SessionRulesRun spends the held review entry and dispatches the exact reviewed call with
783	// the entry's token. The entry is deleted on ANY spend attempt so nothing here is replayable.
784	func (s *Server) ui2SessionRulesRun(w http.ResponseWriter, r *http.Request) {
785		_ = r.ParseForm()
786		fail := func(msg string) {
787			w.Header().Set("Content-Type", "text/html; charset=utf-8")
788			_, _ = w.Write([]byte(ui2Exec("session.html", s.ui2SessionView(msg))))
789		}
790		id := r.PostFormValue("review_id")
791		token := r.PostFormValue("token")
792		v, ok := s.ui2SessionRuleReviews.LoadAndDelete(id)
793		entry, isReview := v.(ui2SessionRuleReview)
794		if !ok || !isReview {
795			fail("that review is unknown or was already used - review the change again")
796			return
797		}
798		if time.Now().After(entry.expires) {
799			fail("that review expired with the confirmation window - review the change again")
800			return
801		}
802		if subtle.ConstantTimeCompare([]byte(entry.token), []byte(token)) != 1 {
803			fail("that review does not match this confirmation - review the change again")
804			return
805		}
806		if entry.domain {
807			// Coordinator-level install: decode the held domain marshal into a FRESH rule (the
808			// entry's bytes are the reviewed change; nothing is re-read or re-merged at run time),
809			// rebuild the extraction matchers the JSON form cannot carry, and install through the
810			// same compare-and-update the API's PUT uses - ValidateRule + NormaliseActions run on
811			// this private copy, then the digest check and swap happen in one lock hold.
812			var merged session.SessionRule
813			if err := json.Unmarshal(entry.body, &merged); err != nil {
814				fail("the held review does not decode - review the change again")
815				return
816			}
817			for _, ex := range merged.Extractions {
818				if ex == nil {
819					continue
820				}
821				if err := ex.Recompile(); err != nil {
822					fail("the held review's extractions do not rebuild - review the change again")
823					return
824				}
825			}
826			err := s.sessionCoordinator.UpdateRuleIfUnchanged(session.RuleID(entry.ruleID), entry.expectedBase, &merged)
827			switch {
828			case errors.Is(err, session.ErrNoSuchRule):
829				fail("that rule no longer exists - nothing was applied")
830			case errors.Is(err, session.ErrRuleChanged):
831				fail("that rule changed since you reviewed it - nothing was applied; open it again and re-review")
832			case err != nil:
833				fail("the session engine refused the change: " + truncateForDisplay(err.Error(), 200))
834			default:
835				// Install-then-persist, the API PUT's ordering.
836				s.persistSessionRules()
837				w.Header().Set("Content-Type", "text/html; charset=utf-8")
838				_, _ = w.Write([]byte(ui2Exec("session.html", s.ui2SessionView(entry.note))))
839			}
840			return
841		}
842		req := newReq(entry.method, entry.url)
843		if entry.body != nil {
844			req.Header.Set("Content-Type", "application/json")
845			req.Body = ioNopCloser(strings.NewReader(string(entry.body)))
846		}
847		req.Header.Set(ConfirmHeader, token)
848		req.Host = "127.0.0.1"
849		req.Header.Set("Origin", "http://127.0.0.1")
850		rec := newRecorder()
851		s.guarded.ServeHTTP(rec, req)
852		switch {
853		case rec.Code == http.StatusPreconditionRequired:
854			fail("confirmation required (428) - the review and the dispatch disagree; review again")
855		case rec.Code == http.StatusConflict:
856			fail("that rule changed since you reviewed it - nothing was applied; open it again and re-review")
857		case rec.Code == http.StatusNotFound:
858			fail("that rule no longer exists - nothing was applied")
859		case rec.Code != http.StatusOK && rec.Code != http.StatusAccepted:
860			fail("the session API refused the change: " + truncateForDisplay(strings.TrimSpace(rec.Body.String()), 200))
861		default:
862			w.Header().Set("Content-Type", "text/html; charset=utf-8")
863			_, _ = w.Write([]byte(ui2Exec("session.html", s.ui2SessionView(entry.note))))
864		}
865	}
