    // A password field's typed value is never carried across a swap: dirty capture + re-apply
    // would keep the secret alive in page state after the sheet that asked for it is gone
    // (triage settings' API key), and re-applying it could silently repopulate a DIFFERENT
    // password field the swap rendered. The operator retypes secrets on the sheet that wants
    // them - exactly once.
    if (t === 'password') continue;
    var checkable = t === 'checkbox' || t === 'radio';
    var isSelect = f.tagName === 'SELECT';
    // A select has no defaultValue: its rendered state lives on the options. And when NO option
    // carries the selected attribute, the browser's default is the first option - comparing
    // selected against defaultSelected alone would read that untouched select as dirty forever,
    // which is exactly how the Scope page's kind picker rendered before this case existed.
    if (isSelect ? (function () {
        var anyDefault = Array.prototype.some.call(f.options, function (o) { return o.defaultSelected; });
        // Untouched defaults differ by arity: a single-select with no selected attribute defaults
        // to its FIRST option; a multiple-select defaults to NOTHING selected.
      for (var k = 0; k < cand.length; k++) {
        if (d.checkable) { if (cand[k].value === d.fvalue) cand[k].checked = d.checked; }
        else { cand[k].value = d.fvalue; }
      }
    }
  }
}

// A swap must never take away something the operator is doing: scrolled position and
// loaded older pages, an open held-message editor on Intercept, a focused field, or any
// unsaved edit inside #rows (the Logger capture filter lives there). Any of those arms
// the pill instead of refreshing; the pill's own refresh re-applies the edits it crosses.
function liveGuarded(what) {
  if (liveScrolled()) return true;
  if (what === 'intercept' || what === 'logger' || what === 'scope' || what === 'sequencer' || what === 'session' || what === 'organizer') {
    var rows = document.getElementById(what === 'scope' ? 'srows' : 'rows');
    if (!rows) return false;
    if (rows.querySelector('details.held-editor[open], details.scope-edit[open], details.collection-edit[open]')) return true;
    var ae = document.activeElement;
    if (ae && rows.contains(ae) && /^(INPUT|TEXTAREA|SELECT)$/.test(ae.tagName)) return true;
    if (liveDirtyFields(rows).length) return true;
    if (what === 'organizer') {
      if (rows.dataset.review === '1' || rows.querySelector('#organizer-note')) return true;
    }
    if (what === 'session') {
      // Operator state beyond form fields: a pending review sheet (its one-time token exists
      // only in this DOM - a swap strands the review) and a rendered outcome note. Both hold
      // the refresh to the pill until the operator asks for it.
      if (rows.dataset.review === '1') return true;
      if (rows.querySelector('#session-note')) return true;
    }
    if (what === 'scope') {
      // The scope review sheet is the same stranded-token state as the session one (its
      // content-bound digests also exist only in this DOM), and the outcome note is the
      // record of what a load or save just did - a refresh must not erase either mid-read.
      if (rows.dataset.review === '1') return true;
      if (rows.querySelector('#scope-note')) return true;
    }
  }
  return false;
}

function liveRefresh(what) {
  if (what !== 'crawlwatch' && liveGuarded(what)) { livePillShow(what); return; }
  if (liveBusy || liveOpFlight > 0) { liveTrailing = what; return; }
  liveIssue(what);
}

function liveIssue(what) {
  var url = '', target = '';
  if (what === 'crawlwatch') {
    var cw = document.getElementById('crawlwatch');
    if (!cw || !cw.dataset.task) return;
    url = '/ui2/scanner/crawl-watch?task=' + encodeURIComponent(cw.dataset.task);
    target = '#crawlwatch';
  } else if (what === 'history') {
    var q = document.getElementById('q');
    var search = document.querySelector('header form input[name="search"]');
    var parts = [];
    if (q && q.value) parts.push('q=' + encodeURIComponent(q.value));
    if (search && search.value) parts.push('search=' + encodeURIComponent(search.value));
    url = '/ui2/history' + (parts.length ? '?' + parts.join('&') : '');
    target = '#rows';
  } else if (what === 'issues') {
    url = '/ui2/issues';
    target = '#rows';
  } else if (what === 'intercept') {
    url = '/ui2/intercept';
    target = '#rows';
  } else if (what === 'logger') {
    var carried = document.querySelector('#rows input[name="search"]');
    url = '/ui2/logger' + (carried && carried.value ? '?search=' + encodeURIComponent(carried.value) : '');
    target = '#rows';
  } else if (what === 'ws') {
    url = '/ui2/ws';
    target = '#rows';
  } else if (what === 'organizer') {
    url = '/ui2/organizer';
    target = '#rows';
  } else if (what === 'proxy') {
    url = '/ui2/proxy';
    target = '#rows';
  } else if (what === 'dashboard') {
    url = '/ui2/dashboard';
    target = '#rows';
  } else if (what === 'session') {
    url = '/ui2/session';
    target = '#rows';
  } else if (what === 'scope') {
    url = '/ui2/scope';
    target = '#srows';
  } else if (what === 'sequencer') {
    url = '/ui2/sequencer';
    target = '#rows';
  } else { return; }
  liveBusy = true;
  htmx.ajax('GET', url, { target: target, swap: 'outerHTML', headers: { 'X-Live-Refresh': what + ':' + liveGen } });
}

// An operator request bumps the generation and counts as in flight until its terminal
// event; live requests carry their generation in the tag and are answered only if it is
// still current. The in-flight count keeps a live refresh from being ISSUED while an
// operator request is outstanding - without it, a live answer read from before the
// operator's change could swap in after the operator's own fresher answer.
// Session add form: each action kind's fields live in a span.kind-fields that starts hidden
// with its controls disabled, so a plain form post carries only the chosen kind's fields (a
// disabled control is never submitted). Ticking a kind's radio shows its block and enables
// exactly its controls; the server still refuses a field that arrives for the wrong kind,
// because that post did not come from the form the operator saw. Delegated, because the form
// is swapped by htmx and listeners on it would not survive.
document.addEventListener('change', function (e) {
  var radio = e.target && e.target.closest ? e.target.closest('#session-rule-controls input[name="action"], .session-action-append input[name="action"]') : null;
  if (!radio || !radio.form) return;
  var spans = radio.form.querySelectorAll('.kind-fields');
  for (var i = 0; i < spans.length; i++) {
    var on = spans[i].getAttribute('data-kind') === radio.value;
    spans[i].hidden = !on;
    var ctrls = spans[i].querySelectorAll('input, select, textarea');
    for (var j = 0; j < ctrls.length; j++) ctrls[j].disabled = !on;
  }
});

document.body.addEventListener('htmx:beforeRequest', function (e) {
  if (!liveTag(e)) { liveGen++; liveOpFlight++; }
});

// Stale live answers are dropped before they can swap over a newer operator action.
document.body.addEventListener('htmx:beforeSwap', function (e) {
  var tag = liveTag(e);
  if (!tag) return;
  var gen = parseInt(tag.split(':')[1], 10);
  if (gen !== liveGen) { e.detail.shouldSwap = false; }
});

// Busy bookkeeping keys on the live tag in requestConfig, not on detail.target (which
// is not reliably an element on error events). Any terminal event of a live request
// frees the slot; a successful answer replays one armed trailing refresh, an error
// stands the follow down - the next frame re-arms it.
// htmx:targetError is deliberately NOT in this list: it fires before any send and its detail
// carries only the hx-target string - no requestConfig - so it can never be matched to a live
// request here. It is also unreachable from liveIssue, whose callers guard that their target

 * with no steps of its own runs the rule's macro below, so materialising the rule's steps into the
 * action here would launder a reference into a copy — the operator would edit the macro underneath
 * and find this action still sending the old text, with nothing on screen saying so.
 */
function actionIn(action: SessionAction): ActionDraft {
 return {
  kind: action.kind,
  enabled: action.enabled,
  stop: action.stop === true,
  macro: (action.macro ?? []).map(stepIn),
  then: (action.then ?? []).map(actionIn),
  else: (action.else ?? []).map(actionIn),
  name: action.name ?? "",
  value: action.value ?? "",
  in: (action.in as ActionDraft["in"]) ?? "",
  match: action.match ?? "",
  replacement: action.replacement ?? "",
  regex: action.regex === true,
  extension: action.extension ?? "",
  script: action.script ?? "",
  validateEvery: action.validate_every ? String(action.validate_every) : "",
  updateWithParams: action.update_with_params === true,
  matchParams: action.match_params ?? "all_params_except",
  params: (action.params ?? []).join(", "),
  tolerateURLMismatch: action.tolerate_url_mismatch === true,
  // Absent is the whole jar, as before the field existed.
  updateWithCookies: action.update_with_cookies !== false,
  matchCookies: action.match_cookies ?? "all_cookies_except",
  cookies: (action.cookies ?? []).join(", "),
 };
}

/** A comma- or newline-separated name list as the wire's array, blanks dropped. */
function nameList(text: string): string[] {
 return text
  .split(/[,\n]/)
  .map((name) => name.trim())
  .filter(Boolean);
}

/**
 * Back to the wire. Fields a kind does not read are omitted rather than sent empty, because the
 * server *refuses* a kind-only field it does not use: sending the whole draft would make every rule
 * with a conditional check unsaveable the moment the editor carried a stray field.
 */
function actionOut(draft: ActionDraft): SessionAction {
 // `label` is deliberately not sent: it is the server's own words for the kind, and echoing a copy
 // back would make the editor's vocabulary look like the client's.
 const out: SessionAction = { kind: draft.kind, label: "", enabled: draft.enabled };
 if (draft.stop) out.stop = true;
 const macro = draft.macro.filter((step) => !isBlankStep(step)).map(stepOut);
 if (macro.length) out.macro = macro;
 if (draft.kind === "check_validity") {
  const then = draft.then.map(actionOut);
  const otherwise = draft.else.map(actionOut);
  if (then.length) out.then = then;
  if (otherwise.length) out.else = otherwise;
  // Only a positive whole number: the server refuses a negative interval, and sending a half-typed
  // "-" or "" as 0 would silently mean "check every request" for a field still being typed.
  const every = Number(draft.validateEvery.trim());
  if (Number.isInteger(every) && every > 0) out.validate_every = every;
 }
 switch (draft.kind) {
  case "set_cookie":
  case "set_header":
   out.name = draft.name.trim();
   out.value = draft.value;
   break;
  case "set_param":
   out.name = draft.name.trim();
   out.value = draft.value;
   if (draft.in) out.in = draft.in;
   break;
  case "replace":
   out.match = draft.match;
   out.replacement = draft.replacement;
   if (draft.regex) out.regex = true;
   break;
  case "invoke_extension":
   out.extension = draft.extension.trim();
   break;
  case "run_script":
   // Sent as typed: whitespace and line breaks are part of the program.
   out.script = draft.script;
   break;
  case "run_macro": {
   // Only what differs from the absent defaults is sent, so an action nobody touched keeps the
   // stored shape it had.
   if (draft.updateWithParams) {
    out.update_with_params = true;
    const params = nameList(draft.params);
    if (draft.matchParams === "specified_params") out.match_params = "specified_params";
    if (params.length) out.params = params;
    if (draft.tolerateURLMismatch) out.tolerate_url_mismatch = true;
   }
   if (!draft.updateWithCookies) {
    out.update_with_cookies = false;
   } else {
    const cookies = nameList(draft.cookies);
    if (draft.matchCookies === "specified_cookies") out.match_cookies = "specified_cookies";
    if (cookies.length) out.cookies = cookies;
   }
   break;
  }
  default:
   break;
 }
 return out;
}

/** One fresh action of a kind, with the fields that kind requires pre-filled where there is a choice. */
function emptyAction(kind: string): ActionDraft {
 return {
  kind,
  enabled: true,
  stop: false,
  macro: [],
  then: [],
  else: [],
  name: "",
  value: "",
  in: "",
  match: "",
  replacement: "",
  regex: false,
  extension: "",
  script: "",
  validateEvery: "",
  // A new macro action updates the request's parameters, as Burp's editor starts out.
  updateWithParams: kind === "run_macro",
  matchParams: "all_params_except",
  params: "",
  tolerateURLMismatch: false,
  updateWithCookies: true,
  matchCookies: "all_cookies_except",
  cookies: "",
 };
}

function ruleIn(rule: SessionRuleFull): RuleDraft {
 const draft: RuleDraft = {
  name: rule.name,
  enabled: rule.enabled,
  hosts: (rule.scope?.rules ?? []).map((entry) => entry.host ?? "").filter(Boolean),
  // URL scope (7nh2): the mode and custom arms ride the scope block.
  scopeMode: (rule.scope?.mode as RuleDraft["scopeMode"]) ?? "all",
function ActionCard({
 action,
 index,
 total,
 depth,
 palette,
 ruleStepCount,
 disabled,
 path,
 refusal,
 onChange,
 onMove,
 onRemove,
}: {
 action: ActionDraft;
 index: number;
 /** This card's position in the server's numbering ("action 2 → then 1"), so a save refusal that
  *  names an action is shown on that action rather than only in a toast. */
 path: string;
 /** The last save refusal that named an action, or null. Shown when its path is this card's. */
 refusal: { path: string; message: string } | null;
 total: number;
 depth: number;
 palette: { kind: string; label: string }[];
 /** How many steps the rule's own macro has, so a RunMacro action can say what it will replay. */
 ruleStepCount: number;
 disabled?: boolean;
 onChange: (next: ActionDraft) => void;
 onMove: (delta: number) => void;
 onRemove: () => void;
}): JSX.Element {
 const label = palette.find((entry) => entry.kind === action.kind)?.label ?? action.kind;
 const isCheck = action.kind === "check_validity";
 const isMacro = action.kind === "run_macro" || action.kind === "run_post_request_macro";
 const patch = (next: Partial<ActionDraft>) => onChange({ ...action, ...next });

 const branch = (which: "then" | "else") => (
  <div className="stack-tight">
   <span className="eyebrow">{which === "then" ? "If the session is valid" : "If it is not (or cannot be told)"}</span>
   {action[which].length === 0 ? (
    <small className="field-hint">
     {which === "then"
      ? "Nothing runs when the check says the session is valid."
      : "Nothing runs when the check says the session is not valid. An undecidable check takes this branch too — reading \u201cI could not tell\u201d as \u201cit is fine\u201d is the wrong way to fail."}
    </small>
   ) : null}
   {action[which].map((child, childIndex) => (
    <ActionCard
     key={childIndex}
     action={child}
     index={childIndex}
     path={actionPath(path, childIndex, which)}
     refusal={refusal}
     total={action[which].length}
     depth={depth + 1}
     palette={palette}
     ruleStepCount={ruleStepCount}
     disabled={disabled}
     onChange={(next) => patch({ [which]: action[which].map((value, i) => (i === childIndex ? next : value)) } as Partial<ActionDraft>)}
     onMove={(delta) => {
      const list = [...action[which]];
      const to = childIndex + delta;
      if (to < 0 || to >= list.length) return;
      const moved = list[childIndex];
      const target = list[to];
      if (moved === undefined || target === undefined) return;
      list[to] = moved;
      list[childIndex] = target;
      patch({ [which]: list } as Partial<ActionDraft>);
     }}
     onRemove={() => patch({ [which]: action[which].filter((_, i) => i !== childIndex) } as Partial<ActionDraft>)}
    />
   ))}
   <div className="inline-add">
    <Select
     aria-label={`Add an action to the ${which} branch`}
     title={`Add an action to the ${which} branch`}

	}
}

// The add form offers exactly the kinds the page can create - no implicit default, every
// per-kind block hidden with its controls disabled in the markup (so a plain post from any
// browser carries only the chosen kind's fields), and the copy names only the kinds and
// shapes that genuinely stay in the console.
func TestUI2SessionRuleAddFormOffersThePageKinds(t *testing.T) {
	s := newTestServerWithCoordinator(t)
	rec := get(t, s, "/ui2/session")
	body := rec.Body.String()
	for _, kind := range []string{
		"add_cookies_from_jar", "set_cookie", "set_header", "set_param",
		"replace", "run_script", "prompt_for_browser_recovery",
	} {
		if !strings.Contains(body, `value="`+kind+`"`) {
			t.Errorf("the add form does not offer %s", kind)
		}
	}
	for _, blocked := range []string{"run_macro", "run_post_request_macro", "check_validity", "invoke_extension"} {
		if strings.Contains(body, `value="`+blocked+`"`) {
			t.Errorf("the add form offers %s, which stays in the console", blocked)
		}
	}
	for _, kind := range []string{"set_cookie", "set_header", "set_param", "replace", "run_script"} {
		i := strings.Index(body, `data-kind="`+kind+`" hidden`)
		if i < 0 {
			t.Fatalf("the %s block is not hidden in the markup", kind)
		}
		j := len(body)
		if k := strings.Index(body[i+1:], `<span class="kind-fields"`); k >= 0 {
			j = i + 1 + k
		}
		for _, field := range []string{`name="action_`} {
			k := strings.Index(body[i:j], field)
			if k < 0 || !strings.Contains(body[i:j][k:], "disabled") {
				t.Errorf("the %s block's fields are not disabled in the markup", kind)
			}
		}
	}
	if !strings.Contains(body, "Macro, validity and extension fields stay in the console. Existing rules offer ordered action-list controls below.") {
		t.Error("the form copy does not name exactly the deferred kinds and shapes")
	}
}

